 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 Drawable buttonBackground(boolean primary){StateListDrawable states=new StateListDrawable();GradientDrawable pressed=new GradientDrawable();pressed.setColor(primary?0xff0284c7:0xff334155);pressed.setCornerRadius(dp(10));GradientDrawable normal=new GradientDrawable();normal.setColor(primary?0xff0369a1:0xff1e293b);normal.setCornerRadius(dp(10));normal.setStroke(dp(1),primary?0xff38bdf8:0xff475569);states.addState(new int[]{android.R.attr.state_pressed},pressed);states.addState(new int[]{},normal);return states;}
 void button(LinearLayout r,final String label,final Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(17);b.setTextColor(0xfff1f5f9);b.setBackgroundDrawable(buttonBackground(label.equals("连接")));b.setPadding(dp(8),0,dp(8),0);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(label.equals("停止")){action.run();return;}if(connecting){showOperation("请先停止连接，再操作。");return;}if(busy||maintenance){showOperation("正在处理上一项操作，请稍候。");return;}action.run();}});if(actionCount%2==0){actionRow=new LinearLayout(this);actionRow.setOrientation(0);LinearLayout.LayoutParams row=new LinearLayout.LayoutParams(-1,-2);row.topMargin=dp(10);r.addView(actionRow,row);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(56),1);if(actionCount%2==0)lp.rightMargin=dp(5);else lp.leftMargin=dp(5);actionRow.addView(b,lp);actionCount++;}
 void stopConnection(){stopConnectionCore();}
 void stopConnectionCore(){requestStartedAt=0;vpnWaitMs=0;AutoUsbService.pause(this);connectPending=false;permissionPending=false;uiHandler.removeCallbacks(tryConnection);connectionId="stopped-"+UUID.randomUUID();WiredService.stop(this);connecting=false;videoReady=false;setProjectionMode(false);show("已停止。本次插入不再自动重连；重新插拔或点击连接可恢复。");}
 void scheduleConnection(long delay){uiHandler.removeCallbacks(tryConnection);if(!closed)uiHandler.postDelayed(tryConnection,delay);}
 // Legacy probe helpers: no UI entry points remain, kept only so dormant probe classes still compile.
 interface Work{String run()throws Exception;}
 void task(final Work job){task("capability",job);}
 void task(final String phase,final Work job){if(busy)return;busy=true;showOperation("正在处理…");worker.execute(new Runnable(){public void run(){String msg;try{msg=job.run();}catch(Throwable e){msg="操作未完成："+e.getClass().getSimpleName();}final String result=msg;runOnUiThread(new Runnable(){public void run(){busy=false;if(!closed)showOperation(result);}});}});}
 void showOperation(String s){if(!closed&&operationStatus!=null){operationStatus.setText(s);operationStatus.setVisibility(View.VISIBLE);}}
 void show(String s){if(!closed){status.setText(s);if(connectionHint!=null)connectionHint.setText(s+"\n按返回键显示连接面板");}}
 void refreshVideoBlank(){if(videoBlank!=null)videoBlank.setVisibility(connecting&&videoReady?View.GONE:View.VISIBLE);}
 void setProjectionMode(boolean enabled){projectionMode=enabled;refreshVideoBlank();controls.setVisibility(enabled?View.GONE:View.VISIBLE);connectionHint.setVisibility(enabled&&connecting&&!videoReady?View.VISIBLE:View.GONE);if(enabled)getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);preview.post(new Runnable(){public void run(){if(!closed)try{record(MainActivity.this,"projection_layout",new JSONObject().put("projectionMode",projectionMode).put("panelVisible",controls.getVisibility()==View.VISIBLE).put("surfaceWidth",preview.getWidth()).put("surfaceHeight",preview.getHeight()).put("windowWidth",preview.getRootView().getWidth()).put("windowHeight",preview.getRootView().getHeight()));}catch(Exception ignored){}}});}
 static final class ProjectionSurface extends SurfaceView {
  ProjectionSurface(Context c){super(c);}
  protected void onMeasure(int widthSpec,int heightSpec){int w=View.MeasureSpec.getSize(widthSpec),h=View.MeasureSpec.getSize(heightSpec);int width=Math.min(w,h*ProjectionConfig.WIDTH/ProjectionConfig.HEIGHT);setMeasuredDimension(width,width*ProjectionConfig.HEIGHT/ProjectionConfig.WIDTH);}
 }
 static void record(Context c,String name,JSONObject details)throws Exception{DiagnosticLog.record(c,name,details);}

 final Runnable tryConnection=new Runnable(){public void run(){if(closed||!resumed||!connectPending||permissionPending)return;if(busy||maintenance){scheduleConnection(500);return;}if(WiredService.isBusy()){scheduleConnection(500);return;}if(!preview.getHolder().getSurface().isValid()){scheduleConnection(100);return;}connectPending=false;requestConnection();}};
 void requestConnection(){if(connecting||permissionPending)return;if(!resumed||!preview.getHolder().getSurface().isValid()){connectPending=true;scheduleConnection(100);return;}if(WiredService.isBusy()){connectPending=true;scheduleConnection(500);return;}if(requestStartedAt==0)requestStartedAt=SystemClock.elapsedRealtime();Intent permission=VpnService.prepare(this);try{record(this,"VPN_PERMISSION_CHECK",new JSONObject().put("required",permission!=null).put("uptimeMs",SystemClock.elapsedRealtime()));}catch(Exception ignored){}if(permission!=null){vpnPromptAt=SystemClock.elapsedRealtime();try{record(this,"VPN_PERMISSION_PROMPT",new JSONObject().put("uptimeMs",vpnPromptAt));}catch(Exception ignored){}permissionPending=true;show("此旧系统每次开机首次连接需确认 VPN，用于 iPhone USB 网络。照片/视频访问不是 CarPlay 授权。请停车后操作。");startActivityForResult(permission,11);}else connectPort();}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if((i.getBooleanExtra("auto_connect",false)||UsbManager.ACTION_USB_DEVICE_ATTACHED.equals(i.getAction()))&&AutoUsbService.canConnect(this)&&!connecting){connectPending=true;scheduleConnection(0);}}
