 public static boolean wheelProbeActive(){return false;}
 public boolean dispatchKeyEvent(KeyEvent event){
  int code=event.getKeyCode();boolean handled=false;String decision="pass_through";
  if(WiredService.consumeWheelDuplicate(code)){handled=true;decision="duplicate_suppressed";}
  else if(code==KeyEvent.KEYCODE_VOLUME_UP||code==KeyEvent.KEYCODE_VOLUME_DOWN){
   if(event.getAction()==KeyEvent.ACTION_DOWN){WiredService.adjustCarPlayVolume(code==KeyEvent.KEYCODE_VOLUME_UP?android.media.AudioManager.ADJUST_RAISE:android.media.AudioManager.ADJUST_LOWER);decision="volume_adjusted";}else decision="volume_release";
   handled=WiredService.isVideoReady();if(!handled)decision="volume_passthrough";
  }else if(event.getAction()==KeyEvent.ACTION_UP&&event.getRepeatCount()==0){
   handled=WiredService.sendWheelKey(code,"activity_dispatch");decision=handled?"wheel_forwarded":"wheel_unmapped_or_no_session";
  }else if(event.getAction()==KeyEvent.ACTION_DOWN)decision="key_down_observed";
  boolean delivered=handled||super.dispatchKeyEvent(event);
  if(event.getAction()==KeyEvent.ACTION_DOWN||event.getAction()==KeyEvent.ACTION_UP&&event.getRepeatCount()<=1){
   boolean known=code==KeyEvent.KEYCODE_VOLUME_UP||code==KeyEvent.KEYCODE_VOLUME_DOWN||code==KeyEvent.KEYCODE_MEDIA_NEXT||code==KeyEvent.KEYCODE_MEDIA_PREVIOUS||code==KeyEvent.KEYCODE_HEADSETHOOK||code==KeyEvent.KEYCODE_CALL||code==KeyEvent.KEYCODE_ENDCALL||CarPlayMediaButton.INSTANCE.opensSiri(code)||CarPlayMediaButton.INSTANCE.opensSiriWhileCarPlay(code);
   if(WiredService.isVideoReady()||known)try{record(this,"WHEEL_KEY",new JSONObject().put("keyPath","activity_dispatch").put("keyCode",code).put("keyAction",event.getAction()).put("keyRepeatCount",event.getRepeatCount()).put("keySource",event.getSource()).put("keyFlags",event.getFlags()).put("keyDecision",decision).put("keyHandled",delivered).put("keyIsSiriCandidate",CarPlayMediaButton.INSTANCE.opensSiri(code)||CarPlayMediaButton.INSTANCE.opensSiriWhileCarPlay(code)));}catch(Exception ignored){}
  }
  return delivered;
 }
 void lifecycle(String event){try{record(this,"PROJECTION_UI",new JSONObject().put("event",event).put("connection",connectionId).put("surfaceValid",preview.getHolder().getSurface().isValid()));}catch(Exception ignored){}}
 void restoreConnection(){String id=WiredService.currentConnectionId();if(id.length()>0){boolean restored=!connecting||!id.equals(connectionId);connectionId=id;connecting=true;connectPending=false;videoReady=WiredService.isVideoReady();if(preview.getHolder().getSurface().isValid())WiredService.attachSurface(this,preview.getHolder().getSurface());if(restored){show(videoReady?"CarPlay 会话已恢复显示":"正在建立 CarPlay 连接");setProjectionMode(true);}}else if(connecting){connecting=false;videoReady=false;setProjectionMode(false);}}

 void connectPort(){if(connecting){show("正在连接，请先停止再重试。");return;}if(requestStartedAt==0)requestStartedAt=SystemClock.elapsedRealtime();if(!preview.getHolder().getSurface().isValid()){show("画面尚未就绪");return;}connecting=true;videoReady=false;show("正在连接iPhone，请在手机和车机上确认授权");setProjectionMode(true);WiredService.attachSurface(this,preview.getHolder().getSurface());try{connectionId=UUID.randomUUID().toString();startService(new Intent(this,WiredService.class).putExtra("connection_id",connectionId).putExtra("request_started_at",requestStartedAt).putExtra("vpn_wait_ms",vpnWaitMs));}catch(RuntimeException e){requestStartedAt=0;vpnWaitMs=0;connecting=false;setProjectionMode(false);show("无法启动连接："+e.getClass().getSimpleName());}}
 final BroadcastReceiver portStatus=new BroadcastReceiver(){public void onReceive(Context c,Intent i){String id=i.getStringExtra("connection_id");if(id!=null&&!id.equals(connectionId))return;show(i.getStringExtra("message"));String stage=i.getStringExtra("stage");if("VIDEO_READY".equals(stage)){videoReady=true;refreshVideoBlank();connectionHint.setVisibility(View.GONE);}if("DISCONNECTED".equals(stage)||"STOPPED".equals(stage)||"FAILED".equals(stage)){requestStartedAt=0;vpnWaitMs=0;connecting=false;videoReady=false;setProjectionMode(false);}}};
 public void onBackPressed(){if(projectionMode){setProjectionMode(false);return;}if(connecting){setProjectionMode(true);return;}super.onBackPressed();}
 protected void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(r==20||r==21){maintenance=false;AutoUsbService.endMaintenance(this);return;}if(r==11){if(!permissionPending)return;permissionPending=false;vpnWaitMs+=Math.max(0,SystemClock.elapsedRealtime()-vpnPromptAt);try{record(this,"VPN_PERMISSION_RESULT",new JSONObject().put("granted",code==RESULT_OK).put("waitMs",vpnWaitMs));}catch(Exception ignored){}if(code==RESULT_OK){connectPending=true;scheduleConnection(0);}else{requestStartedAt=0;vpnWaitMs=0;connectPending=false;AutoUsbService.pause(this);show("未授权VPN，本次自动连接已暂停。");}}}
 static JSONArray snapshot(Context c)throws Exception{return DiagnosticLog.snapshot(c);}
 static void acknowledge(Context c,JSONArray rows)throws Exception{DiagnosticLog.acknowledge(c,rows);}
 String asset(String name)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(getAssets().open(name),"UTF-8"));try{return r.readLine().trim();}finally{r.close();}}
 String uploadNow()throws Exception{String batchToken=UsbBatchReport.append(this);JSONArray rows=snapshot(MainActivity.this);if(rows.length()==0)return "暂时没有日志。连接或运行后即可提交。";
  JSONArray wireRows=ReportIo.wireRows(rows,asset("token.txt"));JSONObject body=new JSONObject().put("app_version","DiPlay-"+getPackageManager().getPackageInfo(getPackageName(),0).versionName).put("sdk",Build.VERSION.SDK_INT).put("model",Build.MODEL).put("comment","有线CarPlay连接日志").put("events",wireRows);byte[] data=body.toString().getBytes("UTF-8");if(data.length>250000)throw new IOException("Report too large");
  File saved=null;try{File folder=new File(Environment.getExternalStorageDirectory(),"DiPlayCompat");saved=ReportIo.backup(folder,data);}catch(IOException error){record(MainActivity.this,"LOG_EXPORT_FAILED",new JSONObject().put("type",error.getClass().getSimpleName()));}
  HttpURLConnection c=(HttpURLConnection)new URL(asset("server.txt")+"/diagnostics").openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setUseCaches(false);c.setRequestProperty("Connection","close");c.setDoOutput(true);c.setFixedLengthStreamingMode(data.length);c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.setRequestProperty("Authorization","Bearer "+asset("token.txt"));NetworkDeadline deadline=new NetworkDeadline(c,45000);try{OutputStream out=c.getOutputStream();out.write(data);out.close();if(c.getResponseCode()!=200)throw new IOException("Upload HTTP "+c.getResponseCode());String id=ReportIo.receipt(c.getInputStream(),wireRows.length());deadline.check();acknowledge(MainActivity.this,rows);UsbBatchReport.acknowledge(this,batchToken);boolean cleared=saved==null||saved.delete();return "提交成功："+id+"\n"+(cleared?"已清理本次已确认日志；并发新日志会保留。":"已确认上传；外部副本清理失败，可手动删除："+saved.getAbsolutePath());}finally{deadline.close();}
 }
 public void onDestroy(){closed=true;connectPending=false;uiHandler.removeCallbacksAndMessages(null);WiredService.detachSurface(this);if(active==this)active=null;unregisterReceiver(portStatus);worker.shutdown();super.onDestroy();}
